-- 생성 파일: scripts/gen-seed.mjs가 data/products.ts에서 만든다. 직접 고치지 않는다.
insert into public.products (id, name, author, price, image_url, description, theme, keeper_note, publisher_description, stock, created_at)
values
  ('b0000000-0000-4000-8000-000000000001', '숲의 시간을 걷다', '한이슬', 16800, 'https://picsum.photos/seed/ub-1/600/800', '계절마다 같은 숲길을 걸으며 기록한 일 년의 산책 일기.', 'nature', '빨리 읽히지 않는 책이에요. 한 계절에 한 장씩, 창밖을 보며 천천히 넘겨 보세요.', '식물 이름을 몰라도 괜찮다. 저자는 이름보다 먼저 냄새와 소리로 숲을 알아 간다.', 5, '2026-10-01T01:00:00.000Z'),
  ('b0000000-0000-4000-8000-000000000002', '새벽 강가의 새들', '도윤재', 19000, 'https://picsum.photos/seed/ub-2/600/800', '금강 하류에서 새를 기다린 열두 번의 새벽과 그림 노트.', 'nature', '책방 창가 자리에서 가장 오래 펼쳐져 있던 책이에요. 그림만 넘겨 봐도 마음이 조용해집니다.', null, 3, '2026-10-03T01:00:00.000Z'),
  ('b0000000-0000-4000-8000-000000000003', '할머니의 장독대', '서미정', 17500, 'https://picsum.photos/seed/ub-3/600/800', '된장과 간장을 담그는 한 해의 순서를 손글씨 레시피와 함께 담았다.', 'food', '레시피 책이지만 이야기책처럼 읽혀요. 장 담그는 날의 햇볕까지 적혀 있습니다.', '음식은 기억을 담는 그릇이다. 세 세대가 같은 장독대 앞에서 나눈 대화를 엮었다.', 4, '2026-10-05T01:00:00.000Z'),
  ('b0000000-0000-4000-8000-000000000004', '제철 밥상 일기', '권하루', 15000, 'https://picsum.photos/seed/ub-4/600/800', '동네 시장에서 그날 나온 재료로 차린 쉰두 번의 밥상 기록.', 'food', '이번 주에는 뭘 먹을까 고민될 때 펼쳐 보는 책이에요. 장바구니가 가벼워집니다.', '거창한 요리가 아니라 매일의 밥. 계절을 먹는다는 말의 뜻을 차근차근 보여 준다.', 0, '2026-10-07T01:00:00.000Z'),
  ('b0000000-0000-4000-8000-000000000005', '작은 생물들의 도시', '나은결', 18000, 'https://picsum.photos/seed/ub-5/600/800', '보도블록 틈과 담벼락에 사는 곤충·이끼·지의류를 따라간 도시 생태 관찰기.', 'ecology', '출근길이 달라 보이게 하는 책이에요. 다 읽고 나면 걸음이 조금 느려집니다.', '생태는 먼 숲에만 있지 않다. 우리가 매일 밟고 지나가는 자리에서 시작한다.', 6, '2026-10-09T01:00:00.000Z'),
  ('b0000000-0000-4000-8000-000000000006', '물이 지나간 자리', '임바다', 21000, 'https://picsum.photos/seed/ub-6/600/800', '한 줄기 하천이 산에서 바다까지 가는 길을 따라 만난 사람과 생물 이야기.', 'ecology', '지도와 함께 읽으면 더 좋아요. 우리 동네 냇물이 어디로 가는지 궁금해집니다.', null, 2, '2026-10-11T01:00:00.000Z'),
  ('b0000000-0000-4000-8000-000000000007', '골목의 오래된 가게들', '조은빛', 16000, 'https://picsum.photos/seed/ub-7/600/800', '삼십 년 넘게 같은 자리를 지켜 온 동네 가게 열다섯 곳의 주인 인터뷰.', 'local', '우리 책방도 언젠가 이런 가게가 되고 싶다는 마음으로 골랐어요.', '간판은 바래도 문은 매일 열린다. 동네를 지탱하는 작은 가게들의 기록.', 7, '2026-10-13T01:00:00.000Z'),
  ('b0000000-0000-4000-8000-000000000008', '우리 동네 산책 지도', '백소담', 14000, 'https://picsum.photos/seed/ub-8/600/800', '대학가 골목과 천변을 잇는 산책길 열 개를 손그림 지도로 엮었다.', 'local', '책방에 들르는 길에 들고 걸어 보세요. 지도에 없는 골목이 하나씩 생길 거예요.', '동네를 안다는 건 길을 외우는 게 아니라 길에 이야기가 생기는 것이다.', 5, '2026-10-15T01:00:00.000Z')
on conflict (id) do update set
  name = excluded.name,
  author = excluded.author,
  price = excluded.price,
  image_url = excluded.image_url,
  description = excluded.description,
  theme = excluded.theme,
  keeper_note = excluded.keeper_note,
  publisher_description = excluded.publisher_description,
  stock = excluded.stock,
  created_at = excluded.created_at;
